+    private boolean isEscaped(String text, int index) {
+        int precedingBackslashes = 0;
+        for (int i = index - 1; i >= 0 && text.charAt(i) == '\\'; i--) {
+            precedingBackslashes++;
+        }
+        return precedingBackslashes % 2 == 1;
+    }
