    private static final class IntegrityReport {
        private final List<Entry> entries = new ArrayList<>();
        private final List<File> unownedFiles = new ArrayList<>();
        private boolean indexChanged;

        private boolean hasProblems() {
            for (Entry entry : entries) {
                if (entry.broken || entry.resolved || entry.misplaced || entry.occupied || entry.shared || entry.colliding) {
                    return true;
                }
            }
            return !unownedFiles.isEmpty();
        }

        private String message(File folder) {
            StringBuilder result = new StringBuilder("Violation store integrity check failed for ")
                    .append(folder.getAbsolutePath()).append(':');
            appendEntries(result, "broken", entries, entry -> entry.broken);
            appendEntries(result, "resolved", entries, entry -> entry.resolved);
            appendEntries(result, "shared", entries, entry -> entry.shared);
            if (!unownedFiles.isEmpty()) {
                result.append("\nunowned files:");
                for (File file : unownedFiles) {
                    result.append("\n  ").append(file.getName());
                }
            }
            appendEntries(result, "misplaced", entries, entry -> entry.misplaced);
            appendEntries(result, "colliding", entries, entry -> entry.colliding);
            appendEntries(result, "occupied", entries, entry -> entry.occupied);
            return result.toString();
        }

        private void appendEntries(StringBuilder result, String condition, List<Entry> entries, EntryPredicate predicate) {
            List<Entry> matching = new ArrayList<>();
            for (Entry entry : entries) {
                if (predicate.test(entry)) {
                    matching.add(entry);
                }
            }
            matching.sort(Comparator.comparing(entry -> entry.description));
            if (!matching.isEmpty()) {
                result.append("\n").append(condition).append(" entries:");
                for (Entry entry : matching) {
                    result.append("\n  ").append(entry.description).append(" -> ").append(entry.recordedName);
                }
            }
        }
    }

    @FunctionalInterface
    private interface EntryPredicate {
        boolean test(Entry entry);
    }

