+    private static final Pattern FILE_NAME_WORD = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_RANDOM = "random";
+    private static final String FILE_NAMES_DESCRIPTION = "description";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_REPAIR = "repair";
+    private static final String INTEGRITY_FAIL = "fail";
+    private static final String INTEGRITY_IGNORE = "ignore";
+
+    /* The lock is deliberately shared by all store instances in this JVM. */
+    private static final ConcurrentHashMap<String, StoreState> STORE_STATES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean strategyProvidedToConstructor;
+
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private StoreState storeState;
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+
+    /**
+     * Creates a standard store. New files are named randomly by UUID unless {@code default.fileNames} is configured.
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+        strategyProvidedToConstructor = false;
+    }
+
+    /**
+     * Creates a store with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new IllegalArgumentException("Rule violation file name strategy must not be null");
+        }
+        constructorStrategy = ruleViolationFileNameStrategy;
+        strategyProvidedToConstructor = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        IntegrityMode integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE));
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires updating the violation store (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        if (strategyProvidedToConstructor && properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+            throw new StoreInitializationFailedException("Configuring " + FILE_NAMES_PROPERTY_NAME
+                    + " is not allowed when a rule violation file name strategy is supplied to the constructor");
+        }
+        RuleViolationFileNameStrategy strategy = strategyProvidedToConstructor
+                ? constructorStrategy
+                : createConfiguredStrategy(properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM));
+
+        try {
+            storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).getCanonicalFile();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        File storedRulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
+        storeState = STORE_STATES_BY_PATH.computeIfAbsent(storeFolder.getPath(), ignored -> new StoreState());
+        storeState.lock.lock();
+        try {
+            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
+            initializeStoreState(storedRulesFile, integrityMode, strategy);
+            ruleViolationFileNameStrategy = strategy;
+        } finally {
+            storeState.lock.unlock();
+        }
+    }
+
+    private void initializeStoreState(File storedRulesFile, IntegrityMode integrityMode,
+            RuleViolationFileNameStrategy strategy) {
+        boolean folderExists = Files.exists(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS);
+        if (folderExists && !Files.isDirectory(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format("Violation store path is not a folder: %s", storeFolder));
+        }
+
+        boolean indexExists = Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS);
+        if (indexExists && !isRegularDirectFile(storedRulesFile, storeFolder)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store index is not a regular file directly in the store folder: %s", storedRulesFile));
+        }
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+
+        Properties properties = indexExists ? loadProperties(storedRulesFile) : new Properties();
+        IntegrityReport report = null;
+        if (integrityMode != IntegrityMode.IGNORE) {
+            report = inspect(properties, strategy);
+            if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
+                throw new StoreInitializationFailedException(report.message(storeFolder));
+            }
+        }
+
+        if (!indexExists) {
+            createStoreFolderAndIndex(storedRulesFile);
+            storeState.indexFile = storedRulesFile;
+            storeState.properties = properties;
+        } else {
+            storeState.indexFile = storedRulesFile;
+            storeState.properties = properties;
+        }
+
+        if (integrityMode == IntegrityMode.REPAIR && report != null && report.hasProblems()) {
+            Properties repairedProperties = copyOf(properties);
+            repair(report, repairedProperties);
+            if (report.indexChanged) {
+                writeProperties(storedRulesFile, repairedProperties);
+                storeState.properties = repairedProperties;
+            }
+        }
+    }
+
+    private void createStoreFolderAndIndex(File storedRulesFile) {
+        if (!storeFolder.mkdirs() && !storeFolder.isDirectory()) {
+            throw new StoreInitializationFailedException(String.format("Cannot create rule store at %s", storedRulesFile));
+        }
+        try {
+            if (!Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                Files.createFile(storedRulesFile.toPath());
+            }
+            if (!isRegularDirectFile(storedRulesFile, storeFolder)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Violation store index is not a regular file directly in the store folder: %s", storedRulesFile));
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadProperties(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private Properties copyOf(Properties source) {
+        Properties result = new Properties();
+        result.putAll(source);
+        return result;
+    }
+
+    private RuleViolationFileNameStrategy createConfiguredStrategy(String configured) {
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            return description -> UUID.randomUUID().toString();
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return new DescriptionFileNameStrategy();
+        }
+        try {
+            Class<?> strategyClass = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)
+                    || !Modifier.isPublic(strategyClass.getModifiers())) {
+                throw new IllegalArgumentException("not a public RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            if (!Modifier.isPublic(constructor.getModifiers())) {
+                throw new IllegalArgumentException("does not have a public no-argument constructor");
+            }
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured through %s='%s'", RuleViolationFileNameStrategy.class.getSimpleName(),
+                    FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        withState();
+        storeState.lock.lock();
+        try {
+            return storeState.properties.containsKey(normalize(rule.getDescription()));
+        } finally {
+            storeState.lock.unlock();
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        withState();
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        storeState.lock.lock();
+        try {
+            saveUnderLock(rule, violations);
+        } finally {
+            storeState.lock.unlock();
+        }
+    }
+
+    private void saveUnderLock(ArchRule rule, List<String> violations) {
+        String description = normalize(rule.getDescription());
+        String existingFileName = storeState.properties.getProperty(description);
+        boolean knownRule = existingFileName != null;
+
+        if (!knownRule && violations.isEmpty() && currentIntegrityModeIsRepair()) {
+            return;
+        }
+
+        String fileName = knownRule ? existingFileName : checkedFileName(rule.getDescription(), true);
+        File writeTarget = checkedOwnedTarget(fileName, knownRule);
+
+        if (currentIntegrityModeIsRepair() && knownRule && violations.isEmpty()) {
+            removeEmptyKnownRule(description, fileName, writeTarget);
+            return;
+        }
+
+        File temporaryFile = null;
+        boolean targetExisted = Files.exists(writeTarget.toPath(), LinkOption.NOFOLLOW_LINKS);
+        try {
+            temporaryFile = File.createTempFile(".stored-rule-", ".tmp", storeFolder);
+            writeViolationFile(temporaryFile, violations);
+            moveReplacing(temporaryFile.toPath(), writeTarget.getCanonicalFile().toPath());
+            temporaryFile = null;
+
+            if (!knownRule) {
+                Properties updated = copyOf(storeState.properties);
+                updated.setProperty(description, normalize(fileName));
+                try {
+                    writeProperties(storeState.indexFile, updated);
+                    storeState.properties = updated;
+                } catch (RuntimeException e) {
+                    if (!targetExisted) {
+                        deleteIfExists(writeTarget);
+                    }
+                    throw e;
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporaryFile != null) {
+                deleteIfExists(temporaryFile);
+            }
+        }
+    }
+
+    private void removeEmptyKnownRule(String description, String fileName, File writeTarget) {
+        if (fileIsSharedByAnotherEntry(description, fileName, writeTarget)) {
+            Properties updated = copyOf(storeState.properties);
+            updated.remove(description);
+            writeProperties(storeState.indexFile, updated);
+            storeState.properties = updated;
+            return;
+        }
+
+        try {
+            deleteOwnedFile(fileName, writeTarget);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException("Cannot delete the violation file for rule '" + description + "'", e);
+        }
+        Properties updated = copyOf(storeState.properties);
+        updated.remove(description);
+        try {
+            writeProperties(storeState.indexFile, updated);
+            storeState.properties = updated;
+        } catch (RuntimeException e) {
+            throw e;
+        }
+    }
+
+    private boolean currentIntegrityModeIsRepair() {
+        /* The mode is fixed for the lifetime of an initialized store. */
+        return integrityMode == IntegrityMode.REPAIR;
+    }
+
+    private IntegrityMode integrityMode = IntegrityMode.IGNORE;
+
+    private String checkedFileName(String description, boolean needed) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreUpdateFailedException("Could not derive a violation file name for rule '" + description + "'", e);
+        }
+        if (needed && (result == null || result.isEmpty())) {
+            throw new StoreUpdateFailedException("Rule violation file name strategy yielded no name for rule '" + description + "'");
+        }
+        return result;
+    }
+
+    private File checkedOwnedTarget(String fileName, boolean knownRule) {
+        if (fileName == null || fileName.isEmpty()) {
+            throw new StoreUpdateFailedException("Rule violation file name strategy yielded no name");
+        }
+        File target;
+        try {
+            target = new File(storeFolder, fileName).getCanonicalFile();
+            File folder = storeFolder.getCanonicalFile();
+            if (!folder.equals(target.getParentFile()) || target.equals(storeState.indexFile.getCanonicalFile())) {
+                throw new StoreUpdateFailedException("Refusing to write a violation file outside the store folder or over the index: " + fileName);
+            }
+            Path targetPath = target.toPath();
+            if (Files.exists(targetPath, LinkOption.NOFOLLOW_LINKS)
+                    && (!Files.isRegularFile(targetPath) || !Files.isRegularFile(targetPath, LinkOption.NOFOLLOW_LINKS)
+                    && !Files.isSymbolicLink(targetPath))) {
+                throw new StoreUpdateFailedException("Refusing to write over a non-file store entry: " + fileName);
+            }
+            if (!knownRule && Files.exists(targetPath, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreUpdateFailedException("Refusing to write over a file not recorded by the rule's entry: " + fileName);
+            }
+            if (!knownRule && anyEntryRecords(fileName)) {
+                throw new StoreUpdateFailedException("A different rule already records violation file: " + fileName);
+            }
+            return target;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private boolean anyEntryRecords(String fileName) {
+        for (String value : storeState.properties.stringPropertyNames()) {
+            if (fileName.equals(storeState.properties.getProperty(value))) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private void withState() {
+        if (storeState == null || storeFolder == null || ruleViolationFileNameStrategy == null) {
+            throw new IllegalStateException("Violation store has not been initialized");
+        }
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        withState();
+        storeState.lock.lock();
+        try {
+            String fileName = storeState.properties.getProperty(normalize(rule.getDescription()));
+            checkArgument(fileName != null, "No rule stored with description '%s'", rule.getDescription());
+            File file = checkedReadTarget(fileName);
+            List<String> result = readLines(file);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        } finally {
+            storeState.lock.unlock();
+        }
+    }
+
+    private File checkedReadTarget(String fileName) {
+        try {
+            File target = new File(storeFolder, fileName).getCanonicalFile();
+            if (!storeFolder.equals(target.getParentFile())) {
+                throw new StoreReadException(new IOException("Violation file is outside the store folder: " + fileName));
+            }
+            return target;
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private List<String> readLines(File file) {
+        String violationsText = readStoreFile(file);
+        List<String> result = new ArrayList<>();
+        StringBuilder current = new StringBuilder();
+        for (int i = 0; i < violationsText.length(); i++) {
+            char character = violationsText.charAt(i);
+            if (character == '\n') {
+                if (current.length() > 0) {
+                    result.add(unescape(current.toString()));
+                }
+                current.setLength(0);
+            } else if (character == '\r') {
+                if (isEscaped(violationsText, i)) {
+                    current.append(character);
+                } else {
+                    if (current.length() > 0) {
+                        result.add(unescape(current.toString()));
+                    }
+                    current.setLength(0);
+                    if (i + 1 < violationsText.length() && violationsText.charAt(i + 1) == '\n') {
+                        i++;
+                    }
+                }
+            } else {
+                current.append(character);
+            }
+        }
+        if (current.length() > 0) {
+            result.add(unescape(current.toString()));
+        }
+        return result;
+    }
+
+    private boolean isEscaped(String text, int index) {
+        int precedingBackslashes = 0;
+        for (int i = index - 1; i >= 0 && text.charAt(i) == '\\'; i--) {
+            precedingBackslashes++;
+        }
+        return precedingBackslashes % 2 == 1;
+    }
+
+    private String readStoreFile(File file) {
+        try {
+            return new String(toByteArray(file), UTF_8);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private void writeViolationFile(File file, List<String> violations) throws IOException {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append('\n');
+        }
+        Files.write(file.toPath(), builder.toString().getBytes(UTF_8));
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\r", "\\\r").replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\r", "\r").replace("\\\n", "\n");
+    }
+
+    private boolean fileIsSharedByAnotherEntry(String description, String fileName, File target) {
+        String targetPath;
+        try {
+            targetPath = target.getCanonicalPath();
+        } catch (IOException e) {
+            return true;
+        }
+        for (String otherDescription : storeState.properties.stringPropertyNames()) {
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            String otherName = storeState.properties.getProperty(otherDescription);
+            if (fileName.equals(otherName)) {
+                return true;
+            }
+            try {
+                File other = new File(storeFolder, otherName).getCanonicalFile();
+                if (targetPath.equals(other.getCanonicalPath()) && Files.isRegularFile(target.toPath())) {
+                    return true;
+                }
+            } catch (IOException ignored) {
+                // A malformed other entry cannot make a safe file deletion less safe.
+            }
+        }
+        return false;
+    }
+
+    private void deleteOwnedFile(String fileName, File resolvedTarget) throws IOException {
+        File namedFile = new File(storeFolder, fileName);
+        if (Files.isSymbolicLink(namedFile.toPath())) {
+            Files.deleteIfExists(resolvedTarget.toPath());
+            Files.deleteIfExists(namedFile.toPath());
+        } else {
+            Files.deleteIfExists(resolvedTarget.toPath());
+        }
+    }
+
+    private void repair(IntegrityReport report, Properties repairedProperties) {
+        for (Entry entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                repairedProperties.remove(entry.description);
+                report.indexChanged = true;
+            } else if (entry.resolved) {
+                try {
+                    deleteOwnedFile(entry.recordedName, entry.resolvedFile);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException("Cannot delete resolved violation file '" + entry.recordedName + "'", e);
+                }
+                repairedProperties.remove(entry.description);
+                report.indexChanged = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                try {
+                    moveOwnedFile(entry);
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException("Cannot move violation file '" + entry.recordedName + "'", e);
+                }
+                repairedProperties.setProperty(entry.description, normalize(entry.derivedName));
+                report.indexChanged = true;
+            }
+        }
+    }
+
+    private void moveOwnedFile(Entry entry) throws IOException {
+        File destination = new File(storeFolder, entry.derivedName).getCanonicalFile();
+        Files.move(entry.resolvedFile.toPath(), destination.toPath());
+        File namedFile = new File(storeFolder, entry.recordedName);
+        if (Files.isSymbolicLink(namedFile.toPath())) {
+            Files.deleteIfExists(namedFile.toPath());
+        }
+    }
+
+    private IntegrityReport inspect(Properties properties, RuleViolationFileNameStrategy strategy) {
+        IntegrityReport report = new IntegrityReport();
+        List<String> descriptions = new ArrayList<>(properties.stringPropertyNames());
+        Collections.sort(descriptions);
+        for (String description : descriptions) {
+            String normalizedDescription = normalize(description);
+            String recordedName = normalize(properties.getProperty(description));
+            String derivedName = deriveForInspection(strategy, normalizedDescription);
+            Entry entry = new Entry(normalizedDescription, recordedName, derivedName);
+            resolveEntry(entry);
+            report.entries.add(entry);
+        }
+
+        markSharedEntries(report.entries);
+        markCollidingEntries(report.entries);
+        for (Entry entry : report.entries) {
+            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+            if (entry.misplaced) {
+                entry.occupied = !isSafeDestination(entry.derivedName)
+                        || Files.exists(new File(storeFolder, entry.derivedName).toPath(), LinkOption.NOFOLLOW_LINKS)
+                        || recordedByAnotherEntry(report.entries, entry);
+            }
+        }
+        report.unownedFiles.addAll(findUnownedFiles(report.entries));
+        return report;
+    }
+
+    private String deriveForInspection(RuleViolationFileNameStrategy strategy, String description) {
+        String name;
+        try {
+            name = strategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreInitializationFailedException("Could not derive a violation file name for rule '" + description + "'", e);
+        }
+        if (name == null || name.isEmpty()) {
+            throw new StoreInitializationFailedException("Rule violation file name strategy yielded no name for rule '" + description + "'");
+        }
+        return normalize(name);
+    }
+
+    private void resolveEntry(Entry entry) {
+        try {
+            File namedFile = new File(storeFolder, entry.recordedName);
+            File resolvedFile = namedFile.getCanonicalFile();
+            if (!isRegularDirectFile(resolvedFile, storeFolder) || resolvedFile.equals(storeState.indexFile.getCanonicalFile())) {
+                entry.broken = true;
+                return;
+            }
+            entry.resolvedFile = resolvedFile;
+            try {
+                entry.resolved = readLines(resolvedFile).isEmpty();
+            } catch (StoreReadException e) {
+                entry.broken = true;
+            }
+        } catch (IOException e) {
+            entry.broken = true;
+        }
+    }
+
+    private void markSharedEntries(List<Entry> entries) {
+        Map<String, List<Entry>> byName = new HashMap<>();
+        Map<String, List<Entry>> byResolvedPath = new HashMap<>();
+        for (Entry entry : entries) {
+            byName.computeIfAbsent(entry.recordedName, ignored -> new ArrayList<>()).add(entry);
+            if (entry.resolvedFile != null) {
+                try {
+                    byResolvedPath.computeIfAbsent(entry.resolvedFile.getCanonicalPath(), ignored -> new ArrayList<>()).add(entry);
+                } catch (IOException ignored) {
+                    // resolveEntry already classified an inaccessible path as broken.
+                }
+            }
+        }
+        markGroupsShared(byName);
+        markGroupsShared(byResolvedPath);
+    }
+
+    private void markGroupsShared(Map<String, List<Entry>> groups) {
+        for (List<Entry> group : groups.values()) {
+            if (group.size() > 1) {
+                for (Entry entry : group) {
+                    entry.shared = true;
+                }
+            }
+        }
+    }
+
+    private void markCollidingEntries(List<Entry> entries) {
+        Map<String, List<Entry>> byDerivedName = new HashMap<>();
+        for (Entry entry : entries) {
+            byDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+        }
+        markGroupsColliding(byDerivedName);
+    }
+
+    private void markGroupsColliding(Map<String, List<Entry>> groups) {
+        for (List<Entry> group : groups.values()) {
+            if (group.size() > 1) {
+                for (Entry entry : group) {
